#[test]
fn legacy_local_backend_value_preserves_external_ollama_meaning() {
    let json = serde_json::json!({
        "schema_version": AI_STUDIO_PREFERENCES_SCHEMA_VERSION,
        "model_backend": "local",
        "local_model_endpoint": "http://127.0.0.1:22434",
        "local_model_name": "legacy-model:q4"
    });
    let preferences: AiStudioPreferences =
        serde_json::from_value(json).expect("legacy preferences");
    assert_eq!(
        preferences.model_backend,
        ModelBackendPreference::OllamaCompatible
    );
    assert_eq!(preferences.local_model_endpoint, "http://127.0.0.1:22434");
    assert_eq!(preferences.local_model_name, "legacy-model:q4");
}

#[test]
fn missing_backend_in_existing_schema_is_migrated_to_external_ollama() {
    let root = std::env::temp_dir().join(format!(
        "gameengine-ai-prefs-migration-{}",
        std::process::id()
    ));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("preference temp root");
    let path = root.join("preferences.json");
    fs::write(
        &path,
        serde_json::to_vec(&serde_json::json!({
            "schema_version": AI_STUDIO_PREFERENCES_SCHEMA_VERSION,
            "local_model_endpoint": "http://127.0.0.1:33434",
            "local_model_name": "old-model:q5"
        }))
        .expect("serialize legacy preferences"),
    )
    .expect("write legacy preferences");
    let preferences = load_ai_studio_preferences(&path);
    let _ = fs::remove_dir_all(&root);
    assert_eq!(
        preferences.model_backend,
        ModelBackendPreference::OllamaCompatible
    );
    assert_eq!(preferences.local_model_endpoint, "http://127.0.0.1:33434");
    assert_eq!(preferences.local_model_name, "old-model:q5");
}

